pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v) public {
        // Bound array length to avoid extreme gas usage; keep it wide enough to find the bug
        vm.assume(_tos.length > 0 && _tos.length <= 5);
        // Ensure the external call does not revert because of malformed call, but let genuine reverts happen
        bytes memory cd = abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, _tos[0], v);
        vm.assume(caddress != address(0));
        vm.assume(caddress.code.length > 0);
        (bool success, bytes memory ret) = c.transfer(from, caddress, _tos, v);
        // The reference always returns true when the call does not revert
        assertTrue(success == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v) public {
        vm.assume(_tos.length > 0);
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        bool returned = success && abi.decode(ret, (bool));
        assertTrue(success ? returned == true : true);
    }
}
